import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;

public class CachedThreadPoolDemonstration {
    public static void main(String[] args) {
        // Unbounded thread pool: dangerous if task submission outpaces execution
        ExecutorService cachedPool = Executors.newCachedThreadPool();

        try {
            for (int i = 0; i < 100_000; i++) {
                final int taskId = i;
                cachedPool.execute(() -> {
                    try {
                        // Simulate blocking I/O or long-running computation
                        Thread.sleep(10000);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }
                    System.out.println("Completed task: " + taskId);
                });
            }
        } catch (RejectedExecutionException e) {
            System.err.println("Execution rejected: " + e.getMessage());
        } finally {
            cachedPool.shutdown();
        }
    }
}
